const config = $input.first().json.config;
const failures = [];
const isNonEmptyString = (value) => typeof value === 'string' && value.trim().length > 0;
const requireObject = (value, path) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    failures.push(`${path} must be an object`);
    return {};
  }
  return value;
};

if (!config || typeof config !== 'object' || Array.isArray(config)) {
  throw new Error('Client config must be a JSON object');
}

const mapping = requireObject(config.mapping, 'mapping');
for (const field of ['name', 'email', 'phone', 'source', 'message', 'externalId']) {
  if (!isNonEmptyString(mapping[field])) failures.push(`mapping.${field} must be a non-empty string`);
}
if (config.defaults !== undefined) {
  const defaults = requireObject(config.defaults, 'defaults');
  if (defaults.source !== undefined && typeof defaults.source !== 'string') {
    failures.push('defaults.source must be a string');
  }
}

const sheets = requireObject(config.googleSheets, 'googleSheets');
for (const field of ['spreadsheetId', 'leadsSheetName', 'errorsSheetName']) {
  if (!isNonEmptyString(sheets[field])) failures.push(`googleSheets.${field} must be a non-empty string`);
}
const columns = requireObject(sheets.columns, 'googleSheets.columns');
if (!isNonEmptyString(columns.name)) failures.push('googleSheets.columns.name must be a non-empty string');
if (!isNonEmptyString(columns.email) && !isNonEmptyString(columns.phone)) {
  failures.push('googleSheets.columns must include email or phone');
}
const errorColumns = requireObject(sheets.errorColumns, 'googleSheets.errorColumns');
for (const field of ['createdAt', 'requestId', 'stage', 'error']) {
  if (!isNonEmptyString(errorColumns[field])) failures.push(`googleSheets.errorColumns.${field} must be a non-empty string`);
}

const telegram = requireObject(config.telegram, 'telegram');
if (!isNonEmptyString(telegram.chatId)) failures.push('telegram.chatId must be a non-empty string');
if (!isNonEmptyString(telegram.messageTemplate)) {
  failures.push('telegram.messageTemplate must be a non-empty string');
} else {
  const allowedTemplateKeys = new Set(['name', 'email', 'phone', 'source', 'message', 'externalId', 'requestId']);
  const placeholders = [...telegram.messageTemplate.matchAll(/\{\{\s*(\w+)\s*\}\}/g)].map((match) => match[1]);
  for (const key of placeholders) {
    if (!allowedTemplateKeys.has(key)) failures.push(`telegram.messageTemplate contains unknown placeholder {{${key}}}`);
  }
}

if (failures.length > 0) {
  throw new Error(`Invalid client config: ${failures.join('; ')}`);
}

return [{ json: { config } }];

// Pure input normalization: mapping and defaults only.
// Validation and external calls are separate nodes.
const config = $('Validate Client Config').first().json.config;
const rawBody = $('Lead Webhook').first().json.body;
const bodyIsObject = rawBody !== null && typeof rawBody === 'object' && !Array.isArray(rawBody);
const payload = bodyIsObject ? rawBody : {};

const mapping = config.mapping;
const getByPath = (obj, path) => {
  if (typeof path !== 'string' || path.length === 0) return undefined;
  return path.split('.').reduce((acc, key) => (acc === null || acc === undefined ? undefined : acc[key]), obj);
};
const asText = (value) => {
  if (value === null || value === undefined) return null;
  if (typeof value === 'string') {
    const trimmed = value.trim();
    return trimmed.length > 0 ? trimmed : null;
  }
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  return null;
};

const emailRaw = asText(getByPath(payload, mapping.email));
const phoneRaw = asText(getByPath(payload, mapping.phone));
const sourceRaw = asText(getByPath(payload, mapping.source));
const phoneDigits = phoneRaw ? phoneRaw.replace(/\D/g, '') : '';
const phone = phoneDigits.length > 0
  ? (phoneRaw.trim().startsWith('+') ? '+' : '') + phoneDigits
  : null;

const requestId = $execution && $execution.id ? String($execution.id) : null;
const receivedAt = new Date().toISOString();

return [{
  json: {
    lead: {
      name: asText(getByPath(payload, mapping.name)),
      email: emailRaw ? emailRaw.toLowerCase() : null,
      phone,
      source: (sourceRaw || (config.defaults && config.defaults.source) || 'unknown').toLowerCase(),
      message: asText(getByPath(payload, mapping.message)),
      externalId: asText(getByPath(payload, mapping.externalId)),
    },
    meta: { requestId, receivedAt, bodyIsObject },
  },
}];

// Business validation over the normalized Lead.
const { lead, meta } = $input.first().json;
const errors = [];

if (!meta.bodyIsObject) {
  errors.push('Request body must be a JSON object.');
}
if (!lead.name) {
  errors.push('name is required.');
}
if (!lead.email && !lead.phone) {
  errors.push('At least one of email or phone is required.');
}

return [{
  json: {
    lead,
    meta,
    validation: {
      valid: errors.length === 0,
      errors,
    },
  },
}];

const validated = $('Validate Lead').first().json;
const config = $('Validate Client Config').first().json.config;
const columns = config.googleSheets.columns;
const values = {
  createdAt: validated.meta.receivedAt,
  externalId: validated.lead.externalId,
  name: validated.lead.name,
  email: validated.lead.email,
  phone: validated.lead.phone,
  source: validated.lead.source,
  message: validated.lead.message,
  requestId: validated.meta.requestId,
};
const row = {};
for (const [key, header] of Object.entries(columns)) {
  if (typeof header !== 'string' || header.length === 0) continue;
  row[header] = values[key] === null || values[key] === undefined ? '' : values[key];
}
if (Object.keys(row).length === 0) {
  throw new Error('No Google Sheets lead columns are configured');
}
return [{ json: row }];

const validated = $('Validate Lead').first().json;
const config = $('Validate Client Config').first().json.config;
const escapeHtml = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');
const values = {
  name: escapeHtml(validated.lead.name || '-'),
  email: escapeHtml(validated.lead.email || '-'),
  phone: escapeHtml(validated.lead.phone || '-'),
  source: escapeHtml(validated.lead.source || '-'),
  message: escapeHtml(validated.lead.message || '-'),
  externalId: escapeHtml(validated.lead.externalId || '-'),
  requestId: escapeHtml(validated.meta.requestId || '-'),
};
let text = String(config.telegram.messageTemplate);
for (const [key, value] of Object.entries(values)) {
  const pattern = new RegExp(`\\{\\{\\s*${key}\\s*\\}\\}`, 'g');
  text = text.replace(pattern, () => value);
}
if (text.length > 4000) {
  text = `${text.slice(0, 3980).replace(/&[a-zA-Z#0-9]*$/, '')}\n[truncated]`;
}
return [{ json: { text } }];

const validated = $('Validate Lead').first().json;
return [{
  json: {
    response: {
      ok: true,
      status: 'created',
      saved: true,
      notified: true,
      requestId: validated.meta.requestId,
      externalId: validated.lead.externalId,
    },
  },
}];

const validated = $('Validate Lead').first().json;
return [{
  json: {
    response: {
      ok: false,
      error: 'validation_error',
      message: 'Lead validation failed.',
      details: validated.validation.errors,
      requestId: validated.meta.requestId,
    },
  },
}];

const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Google Sheets append failed';
const validated = $('Validate Lead').first().json;
const meta = validated.meta;
const executionId = $execution && $execution.id ? String($execution.id) : null;

return [{
  json: {
    response: {
      ok: false,
      error: 'crm_write_failed',
      message: 'Lead was not saved to the CRM.',
      saved: false,
      notified: false,
      requestId: meta.requestId,
    },
    log: {
      createdAt: new Date().toISOString(),
      requestId: meta.requestId,
      stage: 'google_sheets_append',
      error: String(detail).slice(0, 2000),
      leadJson: JSON.stringify(validated.lead).slice(0, 4000),
      executionId,
    },
  },
}];

const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Telegram send failed';
const validated = $('Validate Lead').first().json;
const meta = validated.meta;
const executionId = $execution && $execution.id ? String($execution.id) : null;

return [{
  json: {
    response: {
      ok: true,
      status: 'saved_with_notification_error',
      saved: true,
      notified: false,
      message: 'Lead saved, but the Telegram notification failed.',
      requestId: meta.requestId,
    },
    log: {
      createdAt: new Date().toISOString(),
      requestId: meta.requestId,
      stage: 'telegram_send',
      error: String(detail).slice(0, 2000),
      leadJson: JSON.stringify(validated.lead).slice(0, 4000),
      executionId,
    },
  },
}];

const payload = $input.first().json;
const log = payload.log;
const config = $('Validate Client Config').first().json.config;
const columns = config.googleSheets.errorColumns;
const row = {};
for (const [key, header] of Object.entries(columns)) {
  if (typeof header !== 'string' || header.length === 0) continue;
  if (log[key] !== undefined && log[key] !== null) row[header] = log[key];
}
if (Object.keys(row).length === 0) {
  throw new Error('No Google Sheets error columns are configured');
}
return [{ json: row }];

const input = $input.first().json;
const rawError = input.error;
const detail = typeof rawError === 'string'
  ? rawError
  : (rawError && (rawError.message || rawError.description)) || input.message || 'Configuration error';
const requestId = $execution && $execution.id ? String($execution.id) : null;

return [{
  json: {
    response: {
      ok: false,
      error: 'configuration_error',
      message: 'Lead intake is not configured correctly or the request could not be normalized.',
      detail: String(detail).slice(0, 500),
      requestId,
    },
  },
}];
